  },
  spaceText: {
    ...Typography.mono,
    fontSize: 14,
    textTransform: "uppercase",
    letterSpacing: 0.5,
  },
  popup: {
    position: "absolute",
    zIndex: 100,
    borderRadius: 8,
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 1,
    elevation: 6,
    shadowColor: "#000",
